'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const escapeHTML = s => String(s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage = {get(k, fallback){try{return JSON.parse(localStorage.getItem(k))??fallback;}catch{return fallback;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{return false;}}};
let completed=storage.get('ttlang-lab-v2-completed',[]), current='overview';
const lessons=window.LESSONS;
const readingLessons=lessons.filter(p=>p.id!=='overview');
completed=[...new Set((Array.isArray(completed)?completed:[]).map(id=>id==='essentials'?'tt-lang':id))].filter(id=>readingLessons.some(p=>p.id===id));storage.set('ttlang-lab-v2-completed',completed);
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();};
function toast(message){$('#toast').textContent=message;$('#toast').style.opacity='1';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.opacity='0',2500);}
function nav(){let html='';lessons.forEach((p,i)=>{if(p.id==='vector-add')html+='<div class="nav-divider">Exercises</div>';if(p.id==='report')html+='<div class="nav-divider">Report</div>';html+=`<a class="nav-item ${p.id===current?'active':''}" href="#${p.id}" ${p.id===current?'aria-current="page"':''}><span class="num">${String(i).padStart(2,'0')}</span><span>${escapeHTML(p.short)}</span>${completed.includes(p.id)?'<span class="done" aria-label="Completed">✓</span>':''}</a>`;});$('#lesson-nav').innerHTML=html;$('#progress-label').textContent=`${completed.length} / ${readingLessons.length}`;$('#progress-bar').style.width=`${completed.length/readingLessons.length*100}%`;}
function highlightCode(el){if(el.dataset.highlighted)return;const raw=el.textContent;el.dataset.raw=raw;const pattern=/(#[^\n]*|^[ \t]*\/\/[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:def|class|return|import|from|as|for|in|if|else|with|raise|True|False|None|constexpr|void|uint32_t|module)\b|\b\d+(?:\.\d+)?\b)/gm;let last=0,out='';for(const m of raw.matchAll(pattern)){out+=escapeHTML(raw.slice(last,m.index));let cls=m[0].startsWith('#')||m[0].trimStart().startsWith('//')?'comment':/^["']/.test(m[0])?'string':/^\d/.test(m[0])?'number':'keyword';out+=`<span class="code-${cls}">${escapeHTML(m[0])}</span>`;last=m.index+m[0].length;}out+=escapeHTML(raw.slice(last));el.innerHTML=out;el.dataset.highlighted='true';}
function wireCode(root=document){$$('pre code',root).forEach(highlightCode);$$('.copy-code',root).forEach(btn=>btn.onclick=async()=>{const code=$('pre code',btn.closest('.code-block'));try{await navigator.clipboard.writeText(code.dataset.raw||code.textContent);btn.textContent='Copied';setTimeout(()=>btn.textContent='Copy',1600);}catch{toast('Select the code to copy it.');}});}
function render(){const route=location.hash.slice(1).split('/')[0];if(route==='essentials'){const anchor=location.hash.slice(1).split('/')[1];const destination=!anchor||['machine','engines'].includes(anchor)?'architecture':'tt-lang';location.replace('#'+destination+(anchor?'/'+anchor:''));return;}if(route==='resources'){location.replace('#overview');return;}current=lessons.some(p=>p.id===route)?route:'overview';const page=lessons.find(p=>p.id===current);document.title=`${page.short} · Tenstorrent Lab`;$('#article').innerHTML=page.html;nav();$('#toc-nav').innerHTML=$$('h2', $('#article')).map(h=>`<a href="#${current}/${h.id}">${escapeHTML(h.textContent)}</a>`).join('');const i=lessons.findIndex(p=>p.id===current);$('#lesson-footer').innerHTML=i>=0?`${current!=='overview'?`<button id="complete-button" class="${completed.includes(current)?'completed':''}">${completed.includes(current)?'✓ Marked as read':'○ Mark this lesson as read'}</button>`:'<span></span>'}${i<lessons.length-1?`<a class="next-link" href="#${lessons[i+1].id}"><small>Next chapter</small>${escapeHTML(lessons[i+1].short)} →</a>`:''}`:'<a class="next-link" href="#overview">← Back to contents</a>';if($('#complete-button'))$('#complete-button').onclick=()=>{completed=completed.includes(current)?completed.filter(id=>id!==current):[...completed,current];storage.set('ttlang-lab-v2-completed',completed);nav();$('#complete-button').classList.toggle('completed',completed.includes(current));$('#complete-button').textContent=completed.includes(current)?'✓ Marked as read':'○ Mark this lesson as read';};wireCode();setupInteractive();$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');const anchor=location.hash.slice(1).split('/')[1];if(anchor){requestAnimationFrame(()=>{const target=document.getElementById(anchor);if(target)target.scrollIntoView();else window.scrollTo(0,0);});}else{window.scrollTo(0,0);} }
function setupInteractive(){setupTTLInteractive();if($('#shape-m')){for(const id of ['m','k','n'])$('#shape-'+id).addEventListener('input',shapeStats);$$('[data-shape]').forEach(b=>b.onclick=()=>{const vs=b.dataset.shape.split(',');['m','k','n'].forEach((x,i)=>$('#shape-'+x).value=vs[i]);shapeStats();});shapeStats();}if($('#ragged-select')){$('#ragged-select').onchange=raggedStats;raggedStats();}if($('#pipeline-tabs')){let selected=0;function choose(i){selected=i;const s=window.PIPELINE[i];$('#pipeline-tabs').innerHTML=window.PIPELINE.map((x,j)=>`<button role="tab" aria-selected="${j===selected}" ${j===selected?'class="active"':''} data-stage="${j}">${escapeHTML(x.label)}</button>`).join('');$('#pipeline-panel').innerHTML=`<h3>${escapeHTML(s.title)}</h3><div class="code-block"><div class="code-top"><span>${escapeHTML(s.file)}</span><button class="copy-code">Copy</button></div><pre><code>${escapeHTML(s.code)}</code></pre></div><small>${s.provenance}</small><div class="trace-explanation">${s.description}</div>`;$$('[data-stage]').forEach(b=>b.onclick=()=>choose(+b.dataset.stage));wireCode($('#pipeline-panel'));}choose(0);}if($('#report-questions')){$('#report-questions').innerHTML=window.QUESTIONS.map((q,i)=>`<div class="question"><div class="question-heading"><span class="q-num">Q${String(i+1).padStart(2,'0')}</span><h3 id="q${i+1}-title">${escapeHTML(q.title)} — ${q.points} points</h3></div><p>${escapeHTML(q.prompt)}</p>${q.details||''}</div>`).join('');wireCode($('#report-questions'));}
if($('#artifact-file'))$('#artifact-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2000000){toast('Choose a text artifact smaller than 2 MB.');return;}const raw=await f.text();$('#artifact-name').textContent=`${f.name} · local file · ${raw.split('\n').length} lines`;$('#artifact-content').textContent=raw.split('\n').map((l,i)=>String(i+1).padStart(4,' ')+'  '+l).join('\n');$('#artifact-output').hidden=false;};}
function shapeStats(){const vals=['m','k','n'].map(x=>Number($('#shape-'+x).value));if(vals.some(x=>!Number.isInteger(x)||x<1||x>16384)){$('#shape-results').innerHTML='<p>Enter integer dimensions from 1 to 16,384.</p>';return;}const [m,k,n]=vals,[mp,kp,np]=vals.map(x=>Math.ceil(x/32)*32);const useful=m*k+k*n+m*n,physical=mp*kp+kp*np+mp*np;$('#shape-results').innerHTML=`<div class="stat-grid"><div class="stat"><small>Padded M / K / N</small><strong>${mp} / ${kp} / ${np}</strong></div><div class="stat"><small>Output tiles</small><strong>${(mp*np/1024).toLocaleString()}</strong></div><div class="stat"><small>A + B + C storage overhead</small><strong>${((physical/useful-1)*100).toFixed(1)}%</strong></div></div><p>A: ${mp} × ${kp}, B: ${kp} × ${np}, C: ${mp} × ${np}. Logical arithmetic: ${(2*m*k*n).toLocaleString()} FLOPs. These are storage and arithmetic estimates; measure runtime on the target.</p>`;}
function raggedStats(){const name=$('#ragged-select').value;const configs={balanced:{b:1024,l:542,total:555008,bars:Array(64).fill(542),caption:'1,024 rows × 542 valid elements'},skewed:{b:1024,l:8192,total:555008,bars:[...Array(60).fill(32),...Array(4).fill(8192)],caption:'960 rows × 32 + 64 rows × 8,192 valid elements'},short:{b:8192,l:96,total:524288,bars:[...Array(32).fill(32),...Array(32).fill(96)],caption:'4,096 rows × 32 + 4,096 rows × 96 valid elements'},long:{b:32,l:16384,total:524288,bars:Array(32).fill(16384),caption:'32 rows × 16,384 valid elements'}};const c=configs[name],physical=Math.ceil(c.b/32)*32*Math.ceil(c.l/32)*32;$('#ragged-stats').innerHTML=`<div class="stat-grid"><div class="stat"><small>Valid elements</small><strong>${c.total.toLocaleString()}</strong></div><div class="stat"><small>Tile-padded elements</small><strong>${physical.toLocaleString()}</strong></div><div class="stat"><small>Useful storage fraction</small><strong>${(100*c.total/physical).toFixed(1)}%</strong></div></div><div class="bars" role="img" aria-label="Row length distribution: ${escapeHTML(c.caption)}">${c.bars.map(h=>`<i style="height:${Math.max(2,h/c.l*100)}%"></i>`).join('')}</div><div class="bar-caption">${escapeHTML(c.caption)}. Bars summarize groups of rows; heights are scaled within this case.</div><p>Storage counts describe x only. A materialized mask and intermediate tensors add traffic. Compare padded storage as well as the valid-element count.</p>`;}
function downloadText(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function setupTTLInteractive(){
  if($('#tile-demo')){
    let m=0,n=0,k=0;
    function matrix(label,rows,cols,active,clickable){let cells='';for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){const selected=active(r,c);cells+=clickable?`<button data-output="${r},${c}" aria-pressed="${selected}" class="${selected?'selected':''}" aria-label="Select output tile C ${r}, ${c}">${r},${c}</button>`:`<span class="${selected?'selected':''}">${r},${c}</span>`;}return `<div class="tile-matrix"><b>${label}</b><div class="tile-cells" style="grid-template-columns:repeat(${cols},1fr)">${cells}</div></div>`;}
    function draw(){$('#tile-demo').innerHTML=matrix('A · 2 × 4 tiles',2,4,(r,c)=>r===m&&c===k,false)+matrix('B · 4 × 3 tiles',4,3,(r,c)=>r===k&&c===n,false)+matrix('C · 2 × 3 tiles',2,3,(r,c)=>r===m&&c===n,true);$('#tile-equation').textContent=`K term ${k+1} of 4: C[${m},${n}] += A[${m},${k}] @ B[${k},${n}]\nA scalar rows ${m*32}…${m*32+31}, K ${k*32}…${k*32+31}; B scalar columns ${n*32}…${n*32+31}.`;$$('[data-output]').forEach(b=>b.onclick=()=>{[m,n]=b.dataset.output.split(',').map(Number);draw();});}
    $('#tile-prev').onclick=()=>{k=(k+3)%4;draw();};$('#tile-next').onclick=()=>{k=(k+1)%4;draw();};draw();
  }

}
$('#menu-toggle').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));};
const dialog=$('#search-dialog');$('#search-open').onclick=()=>{dialog.showModal();$('#search-input').focus();search();};$('#search-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});function search(){const term=$('#search-input').value.trim().toLowerCase();const pages=lessons;const matches=pages.filter(p=>!term||(p.short+' '+p.html.replace(/<[^>]+>/g,' ')+(p.id==='report'?' '+window.QUESTIONS.map(q=>q.title+' '+q.prompt+' '+(q.details||'').replace(/<[^>]+>/g,' ')).join(' '):'')).toLowerCase().includes(term));$('#search-results').innerHTML=matches.length?matches.map(p=>`<a href="#${p.id}">${escapeHTML(p.short)}<small>${escapeHTML(p.summary||'Sources, downloads and artifact provenance')}</small></a>`).join(''):'<p>No matching lesson. Try “IR”, “mask”, or “timing”.</p>';$$('a',$('#search-results')).forEach(a=>a.onclick=()=>dialog.close());}$('#search-input').oninput=search;document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();dialog.showModal();$('#search-input').focus();search();}});window.addEventListener('hashchange',render);render();
